package com.enterpriseos;

import java.io.*;
import java.net.URI;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/** Optional path-style S3-compatible adapter; no bucket/account is created by this service. */
@Service
public class DocumentBlobStore {
    private static final int MAX=5*1024*1024;
    private final Path local;private final String endpoint,bucket,region,access,secret,sessionToken;private final boolean allowHttp;
    private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
    public DocumentBlobStore(@Value("${APP_DOCUMENT_DIR:./var/documents}")String directory,@Value("${APP_OBJECT_STORAGE_ENDPOINT:}")String endpoint,@Value("${APP_OBJECT_STORAGE_BUCKET:}")String bucket,@Value("${APP_OBJECT_STORAGE_REGION:us-east-1}")String region,@Value("${APP_OBJECT_STORAGE_ACCESS_KEY:}")String access,@Value("${APP_OBJECT_STORAGE_SECRET_KEY:}")String secret,@Value("${APP_OBJECT_STORAGE_SESSION_TOKEN:}")String sessionToken,@Value("${APP_OBJECT_STORAGE_ALLOW_HTTP:false}")boolean allowHttp){this.local=Path.of(directory).toAbsolutePath().normalize();this.endpoint=endpoint.replaceAll("/+$","");this.bucket=bucket;this.region=region;this.access=access;this.secret=secret;this.sessionToken=sessionToken;this.allowHttp=allowHttp;}
    public String put(String tenant,String key,byte[] bytes){validateKey(tenant,key);if(bytes.length>MAX)throw new ApiException(400,"Document exceeds its storage size limit.");if(endpoint.isBlank()){Path file=local.resolve(key);try{Files.createDirectories(local);Files.write(file,bytes,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE);try{Files.setPosixFilePermissions(file,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));}catch(UnsupportedOperationException ignored){}return "LOCAL";}catch(IOException ex){throw new ApiException(503,"Private document storage is unavailable.");}}request("PUT",key,bytes);return "S3";}
    public byte[] read(String tenant,String key,String backend){validateKey(tenant,key);if("LOCAL".equals(backend)){Path file=local.resolve(key);try{if(!Files.isRegularFile(file)||Files.size(file)>MAX)throw new ApiException(404,"Stored document is unavailable.");return Files.readAllBytes(file);}catch(IOException ex){throw new ApiException(404,"Stored document is unavailable.");}}if(!"S3".equals(backend))throw new ApiException(503,"Unknown document storage backend.");return request("GET",key,new byte[0]);}
    public void delete(String tenant,String key,String backend){validateKey(tenant,key);if("LOCAL".equals(backend)){try{Files.deleteIfExists(local.resolve(key));}catch(IOException ex){throw new ApiException(503,"Document deletion requires operator cleanup.");}}else if("S3".equals(backend))request("DELETE",key,new byte[0]);else throw new ApiException(503,"Unknown document storage backend.");}
    private void validateKey(String tenant,String key){if(tenant==null||key==null||!key.matches("[0-9a-f-]{73}\\.bin")||!key.startsWith(tenant+"-"))throw new ApiException(404,"Stored document is unavailable.");}
    private byte[] request(String method,String key,byte[] body){URI uri=uri(key);String time=DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'").withZone(ZoneOffset.UTC).format(Instant.now());Map<String,String> headers=new TreeMap<>();headers.put("host",uri.getHost()+(uri.getPort()<0?"":":"+uri.getPort()));headers.put("x-amz-date",time);headers.put("x-amz-content-sha256",sha(body));if(!sessionToken.isBlank())headers.put("x-amz-security-token",sessionToken);String authorization=authorization(method,uri.getRawPath(),headers,body,region,access,secret);var builder=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(20)).header("Authorization",authorization);headers.forEach((name,value)->{if(!name.equals("host"))builder.header(name,value);});var request=builder.method(method,method.equals("PUT")?HttpRequest.BodyPublishers.ofByteArray(body):HttpRequest.BodyPublishers.noBody()).build();try{var response=http.send(request,HttpResponse.BodyHandlers.ofInputStream());try(InputStream stream=response.body()){int code=response.statusCode();if(code==404&&method.equals("DELETE"))return new byte[0];if(code==404)throw new ApiException(404,"Object storage document was not found.");if(code<200||code>=300)throw new ApiException(503,"Object storage rejected the operation. Check configured credentials, bucket and region.");if(!method.equals("GET"))return new byte[0];byte[] result=stream.readNBytes(MAX+1);if(result.length>MAX)throw new ApiException(503,"Object storage returned an oversized document.");return result;}}catch(ApiException ex){throw ex;}catch(InterruptedException ex){Thread.currentThread().interrupt();throw new ApiException(503,"Object storage operation was interrupted.");}catch(Exception ex){throw new ApiException(503,"Object storage is unavailable.");}}
    private URI uri(String key){try{URI base=URI.create(endpoint);if(endpoint.isBlank()||base.getHost()==null||base.getUserInfo()!=null||base.getRawQuery()!=null||base.getFragment()!=null||!Set.of("https","http").contains(base.getScheme())||(!base.getScheme().equals("https")&&!allowHttp)||!bucket.matches("[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]")||!region.matches("[A-Za-z0-9-]{1,40}")||access.isBlank()||secret.isBlank())throw new IllegalArgumentException();return URI.create(endpoint+"/"+bucket+"/"+key);}catch(Exception ex){throw new ApiException(503,"Configure a private HTTPS S3-compatible endpoint, bucket, region and credentials. HTTP requires explicit local-development opt-in.");}}
    public static String authorization(String method,String path,Map<String,String> input,byte[] body,String region,String access,String secret){Map<String,String> headers=new TreeMap<>();input.forEach((k,v)->headers.put(k.toLowerCase(Locale.ROOT),v.trim().replaceAll("\\s+"," ")));String timestamp=headers.get("x-amz-date"),date=timestamp.substring(0,8);StringBuilder canonicalHeaders=new StringBuilder();headers.forEach((k,v)->canonicalHeaders.append(k).append(':').append(v).append('\n'));String signed=String.join(";",headers.keySet()),scope=date+"/"+region+"/s3/aws4_request";String canonical=method+"\n"+path+"\n\n"+canonicalHeaders+"\n"+signed+"\n"+sha(body);String stringToSign="AWS4-HMAC-SHA256\n"+timestamp+"\n"+scope+"\n"+sha(canonical.getBytes(StandardCharsets.UTF_8));byte[] signing=hmac(hmac(hmac(hmac(("AWS4"+secret).getBytes(StandardCharsets.UTF_8),date),region),"s3"),"aws4_request");return "AWS4-HMAC-SHA256 Credential="+access+"/"+scope+",SignedHeaders="+signed+",Signature="+HexFormat.of().formatHex(hmac(signing,stringToSign));}
    private static byte[] hmac(byte[] key,String value){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(key,"HmacSHA256"));return mac.doFinal(value.getBytes(StandardCharsets.UTF_8));}catch(Exception ex){throw new IllegalStateException(ex);}}
    private static String sha(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception ex){throw new IllegalStateException(ex);}}
}
